# Let me analyze this ARC grid puzzle
grid = [
    [0, 0, 8, 9, 0, 5, 6],
    [0, 8, 9, 0, 5, 6, 7],
    [8, 9, 0, 5, 6, 7, 6],
    [9, 0, 5, 6, 7, 6, 3],
    [0, 5, 6, 7, 6, 3, 0],
    [5, 6, 7, 6, 3, 0, 0],
    [6, 7, 6, 3, 0, 0, 2]
]

print(f"Grid size: {len(grid)}x{len(grid[0])}")
print("Input grid:")
for row in grid:
    print(row)

# Let's look at the main diagonal
main_diag = [grid[i][i] for i in range(len(grid))]
print(f"\nMain diagonal: {main_diag}")

# Looking at diagonals more carefully - let me find value relationships
# Check what numbers appear and their positions
numbers = {}
for r in range(len(grid)):
    for c in range(len(grid[0])):
        v = grid[r][c]
        if v not in numbers:
            numbers[v] = []
        numbers[v].append((r, c))

print("\nNumber positions:")
for num in sorted(numbers.keys()):
    print(f"{num}: {numbers[num]}")

# Look for difference patterns - is there a mathematical relationship?
# What if we look at (row + col) or (row - col)?
print("\nLooking at diagonal relationships (row - col):")
queries = {}
for r in range(len(grid)):
    for c in range(len(grid[0])):
        k = grid[r][c]
        d = r - c
        if d not in queries:
            queries[d] = set()
        if k not in queries[d]:
            queries[d].add(k)
    if d not in queries:
        queries.setdefault(d, set()).add(k)

for k in sorted(queries.keys()):
    if len(queries[k]) > 1:  # Things that change along the diagonal
        print(f"Diagonal {k} (r-col): {sorted(queries[k])} appear")

# Let me analyze patterns by r+c and r-c values
grid = [
    [0, 0, 8, 9, 0, 5, 6],
    [0, 8, 9, 0, 5, 6, 7],
    [8, 9, 0, 5, 6, 7, 6],
    [9, 0, 5, 6, 7, 6, 3],
    [0, 5, 6, 7, 6, 3, 0],
    [5, 6, 7, 6, 3, 0, 0],
    [6, 7, 6, 3, 0, 0, 2]
]

def r_c_analysis(grid):
    """Analyze by r+c and r-c"""
    result = {}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            s = r + c
            d = r - c
            v = grid[r][c]

            if s not in result:
                result[s] = {}
            if d not in result:
                result[d] = {}

            if v not in result[s]:
                result[s][v] = []
            result[s][v].append((r, c))

            if v not in result[d]:
                result[d][v] = []
            result[d][v].append((r, c))

    return result

result = r_c_analysis(grid)

print("=== BY r+c (sum) ===")
for s in sorted(result.keys()):
    if len(result[s]) <= 4:  # Few values at this sum - cleaner pattern
        rv = result[s]
        vals = sorted(rv.items())
        print(f"r+c={s}: {vals}")

print("\n=== BY r-c (difference) ===")  
for d in sorted(result.keys()):
    if len(result[d]) <= 4:
        rv = result[d]
        vals = sorted(rv.items())
        print(f"r-c={d}: {vals}")

# Interesting: values that only appear once on a given diagonal
print("\n=== Values with single cells per diagonal band ===")
for s in sorted(result.keys()):
    rv = result[s]
    for v, positions in rv.items():
        if len(positions) == 1:
            print(f"r+c={s}, val={v}: {positions}")

for d in sorted(result.keys()):
    rv = result[d]
    for v, positions in rv.items():
        if len(positions) == 1:
            print(f"r-c={d}, val={v}: {positions}")

